// PhishLens site: server status, live counters and the "try it" form.
// No cookies, no storage, no third-party scripts. The only external call
// is GitHub's public API for the latest version number. The texts come
// from i18n/<lang>.js, generated by scripts/build_site.py.
(() => {
  "use strict";
  const $ = (id) => document.getElementById(id);
  const SITE = window.PhishLensSite || { lang: "en", t: {} };
  const t = (key, vars = {}) =>
    String(SITE.t[key] ?? key).replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m));
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const num = (n) => Number(n || 0).toLocaleString(SITE.lang);
  const pct = (v) => Math.round((Number(v) || 0) * 100);
  // Same-origin on the real site; PhishLens Cloud when the page is opened
  // elsewhere (local preview), which the server allows (CORS).
  const API = location.hostname === "anzouk.duckdns.org" ? "" : "https://anzouk.duckdns.org";

  // ---------- server status ----------
  const status = $("status");
  const setDot = (up) => { $("live-dot").className = `dot ${up ? "dot--up" : "dot--down"}`; };
  fetch(API + "/health", { cache: "no-store" })
    .then((r) => { if (!r.ok) throw new Error(); })
    .then(() => { status.innerHTML = `<span class="dot dot--up"></span> ${esc(t("js_online"))}`; setDot(true); })
    .catch(() => { status.innerHTML = `<span class="dot dot--down"></span> ${esc(t("js_offline"))}`; setDot(false); });

  fetch("https://api.github.com/repos/AnzouK/PhishLens/releases/latest")
    .then((r) => (r.ok ? r.json() : Promise.reject()))
    .then((d) => { if (d.tag_name) $("version").textContent = t("js_version", { v: d.tag_name.replace(/^v/, "") }); })
    .catch(() => {});

  // ---------- live counters, as big numbers ----------
  const cell = (big, lbl, off) => `<div class="cell"><div class="big${off ? " off" : ""}">${esc(big)}</div><div class="lbl">${esc(lbl)}</div></div>`;
  fetch(API + "/reputation/stats", { cache: "no-store" })
    .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`HTTP ${r.status}`))))
    .then((d) => {
      if (d.enabled === false) throw new Error(t("js_intel_off"));
      const c = d.cache || {}, g = d.gsb || {}, p = d.phishtank || {}, u = d.urlhaus || {};
      $("live").innerHTML =
        (g.enabled === false ? cell(t("js_off"), t("js_gsb"), true)
                             : cell(num(g.remaining), t("js_gsb_left", { limit: num(g.limit) })))
        + cell(num((c.hits || 0) + (c.misses || 0)), t("js_links_checked", { pct: pct(c.hit_rate) }))
        + (p.enabled === false || !p.phishtank_entries ? cell(t("js_off"), t("js_phishtank_feed"), true)
                                                       : cell(num(p.phishtank_entries), t("js_phishtank_known")))
        + (u.enabled ? cell(t("js_on"), t("js_urlhaus_on")) : cell(t("js_off"), t("js_urlhaus"), true));
    })
    .catch((e) => { $("live").innerHTML = cell(t("js_unavailable"), e.message || t("js_unreachable"), true); });

  // ---------- try-it form ----------
  const form = $("demo-form");
  const text = $("demo-text"), file = $("demo-file");
  const textErr = $("demo-text-error"), fileErr = $("demo-file-error");
  const submit = $("demo-submit"), out = $("demo-result"), drop = $("drop-zone");
  const submitLabel = submit.textContent;
  const MAX_FILE = 10 * 1024 * 1024;
  const ATTACHMENT_EXTS = new Set(["pdf", "html", "htm", "png", "jpg", "jpeg", "gif", "webp", "docx", "docm", "doc",
                                   "xlsx", "xlsm", "xls", "pptx", "pptm", "ppt", "zip", "rar", "7z", "ics", "txt"]);
  const SAMPLES = {
    phish: "Dear customer,\n\nWe were unable to process your last payment and your account has been suspended. To avoid permanent closure, verify your billing details within 24 hours:\n\nhttp://secure-billing-verify.tk/login?id=48213\n\nFailure to act immediately will result in the loss of all your files.\n\nBilling Department",
    safe: "Hi team,\n\nThe sprint review moved to Thursday at 3pm, same room. I added the agenda to the shared document; please add your items before Wednesday evening.\n\nThanks,\nAmina",
  };
  let mode = "text", chosen = null, lastSubmit = 0;

  function clearErrors() {
    for (const [el, msg] of [[text, textErr], [drop, fileErr]]) { el.removeAttribute("aria-invalid"); msg.textContent = ""; }
  }
  function fail(el, msg, message) {
    el.setAttribute("aria-invalid", "true");
    msg.textContent = message;
    (el === drop ? file : el).focus();
    return null;
  }

  // tabs
  document.querySelectorAll(".tab").forEach((tab) => tab.addEventListener("click", () => {
    mode = tab.id === "tab-file" ? "file" : "text";
    document.querySelectorAll(".tab").forEach((t) => t.setAttribute("aria-selected", String(t === tab)));
    $("pane-text").hidden = mode !== "text";
    $("pane-file").hidden = mode !== "file";
    clearErrors();
  }));

  // examples and clipboard
  form.querySelectorAll("[data-sample]").forEach((b) => b.addEventListener("click", () => {
    text.value = SAMPLES[b.dataset.sample]; clearErrors(); text.focus();
  }));
  $("paste-btn").addEventListener("click", async () => {
    try {
      const clip = await navigator.clipboard.readText();
      if (!clip.trim()) return fail(text, textErr, t("js_clip_empty"));
      text.value = clip.slice(0, 20000); clearErrors(); text.focus();
    } catch {
      fail(text, textErr, t("js_clip_blocked"));
    }
  });
  text.addEventListener("keydown", (e) => {
    if ((e.metaKey || e.ctrlKey) && e.key === "Enter") { e.preventDefault(); form.requestSubmit(); }
  });

  // file: click or drag and drop
  const dropTitle = $("drop-title").textContent;
  const setFile = (f) => {
    chosen = f || null; clearErrors();
    // Long names are cut to two lines by CSS; the size stays visible on
    // its own line and the full name is in the tooltip.
    $("drop-title").textContent = chosen ? chosen.name : dropTitle;
    $("drop-title").title = chosen ? chosen.name : "";
    $("drop-size").textContent = chosen ? t("js_size_kb", { size: num(Math.max(1, Math.round(chosen.size / 1024))) }) : "";
    $("drop-size").hidden = !chosen;
  };
  file.addEventListener("change", () => setFile(file.files[0]));
  ["dragenter", "dragover"].forEach((ev) => drop.addEventListener(ev, (e) => { e.preventDefault(); drop.classList.add("drop--over"); }));
  ["dragleave", "drop"].forEach((ev) => drop.addEventListener(ev, (e) => { e.preventDefault(); drop.classList.remove("drop--over"); }));
  drop.addEventListener("drop", (e) => setFile(e.dataTransfer?.files?.[0]));

  function validate() {
    clearErrors();
    if (mode === "text") {
      const v = text.value.trim();
      if (v.length < 20) return fail(text, textErr, t("js_err_min"));
      if (v.length > 20000) return fail(text, textErr, t("js_err_max"));
      return { endpoint: "/analyse", body: { raw_text: v } };
    }
    if (!chosen) return fail(drop, fileErr, t("js_err_choose"));
    if (chosen.size > MAX_FILE) return fail(drop, fileErr, t("js_err_size", { size: (chosen.size / 1048576).toLocaleString(SITE.lang, { maximumFractionDigits: 1 }) }));
    const ext = (chosen.name.split(".").pop() || "").toLowerCase();
    if (ext !== "eml" && !ATTACHMENT_EXTS.has(ext)) return fail(drop, fileErr, t("js_err_type"));
    return { file: chosen, ext };
  }

  const toB64 = (f) => new Promise((res, rej) => {
    const r = new FileReader();
    r.onload = () => { const s = String(r.result || ""); res(s.slice(s.indexOf(",") + 1)); };
    r.onerror = () => rej(new Error(t("js_err_read")));
    r.readAsDataURL(f);
  });

  function meter(label, v) {
    const p = pct(v), cls = p >= 70 ? " meter__fill--high" : p >= 40 ? " meter__fill--mid" : "";
    return `<div class="meter"><span>${esc(label)}</span><span class="meter__track"><span class="meter__fill${cls}" data-w="${p}"></span></span><span class="meter__v">${p}%</span></div>`;
  }

  function render(d, isEmail) {
    const bad = d.verdict === "phishing";
    const tags = [];
    const sa = d.sender_auth || {};
    if (d.trusted_sender) tags.push(["good", t("js_tag_trusted")]);
    else if (sa.cryptographically_verified) tags.push(["good", t("js_tag_dkim")]);
    for (const k of ["spf", "dkim", "dmarc"]) if (sa[k] === "fail") tags.push(["bad", t("js_tag_auth_fail", { name: k.toUpperCase() })]);
    (d.url_reputation?.sources_hit || []).forEach((s) => tags.push(["bad", t("js_tag_flagged", { source: s.replace(/_/g, " ") })]));
    if (d.forwarded?.detected) tags.push(["warn", t("js_tag_forwarded")]);
    if (d.shared_links?.count) tags.push(["warn", t("js_tag_shared", { services: (d.shared_links.services || []).join(", ") })]);
    const a = d.attachment;
    if (a) (a.notable_features || []).forEach((f) => tags.push(["warn", f.replace(/_/g, " ")]));
    out.innerHTML = `
      <p class="verdict verdict--${bad ? "bad" : "good"}"><svg class="ic"><use href="#i-shield"/></svg>${esc(t(bad ? "js_verdict_bad" : "js_verdict_good"))}</p>
      <p class="small muted">${esc(t("js_overall", { pct: pct(d.fused_score) }))}</p>
      ${meter(t("js_m_wording"), d.agents?.text?.phishing_probability)}
      ${meter(t("js_m_links"), d.agents?.url?.phishing_probability)}
      ${a ? "" : meter(t("js_m_sender"), d.agents?.metadata?.phishing_probability)}
      ${tags.length ? `<ul class="tags">${tags.map(([c, t]) => `<li class="${c}">${esc(t)}</li>`).join("")}</ul>` : ""}
      ${isEmail ? `<h3>${esc(t("js_lime_h"))}</h3><p class="small muted">${esc(t("js_lime_hint"))}</p><div id="lime" class="status"><span class="spinner" aria-hidden="true"></span> ${esc(t("js_computing"))}</div>` : ""}`;
    out.querySelectorAll(".meter__fill").forEach((el) => { el.style.width = `${el.dataset.w}%`; });
  }

  function renderLime(features) {
    const slot = $("lime");
    if (!slot) return;
    features = (features || []).filter((f) => String(f.token || "").length > 2 && !/^\d+$/.test(f.token));
    if (!features.length) { slot.textContent = t("js_no_word"); return; }
    const max = Math.max(...features.map((f) => Math.abs(f.weight))) || 1;
    slot.className = "";
    slot.innerHTML = features.map((f) =>
      `<span class="tok ${f.supports === "phishing" ? "tok--p" : "tok--s"}" data-a="${(0.15 + (Math.abs(f.weight) / max) * 0.45).toFixed(2)}">${esc(f.token)}</span>`).join("");
    slot.querySelectorAll(".tok").forEach((el) => el.style.setProperty("--a", el.dataset.a));
  }

  function showError(title, message) {
    out.innerHTML = `<p class="verdict verdict--bad">${esc(title)}</p><p class="muted">${esc(message)}</p>`;
  }

  form.addEventListener("submit", async (e) => {
    e.preventDefault();
    if ($("website").value) return;                    // honeypot filled: a bot
    const now = Date.now();
    if (now - lastSubmit < 4000) return;               // one check every few seconds
    const v = validate();
    if (!v) return;
    lastSubmit = now;

    let endpoint = v.endpoint, body = v.body;
    if (v.file) {
      try {
        const b64 = await toB64(v.file);
        if (v.ext === "eml") { endpoint = "/analyse"; body = { raw_email_b64: b64 }; }
        else { endpoint = "/analyse_attachment"; body = { content_b64: b64, filename: v.file.name, mime_type: v.file.type || null }; }
      } catch (err) { return fail(drop, fileErr, err.message); }
    }

    submit.disabled = true;
    submit.innerHTML = `<span class="spinner" aria-hidden="true"></span> ${esc(t("js_checking"))}`;
    out.innerHTML = `<p class="status"><span class="spinner" aria-hidden="true"></span> ${esc(t("js_analysing"))}</p>`;
    try {
      const r = await fetch(API + endpoint, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
      const d = await r.json().catch(() => ({}));
      if (r.status === 429) throw new Error(t("js_rate"));
      if (!r.ok) throw new Error(d.detail || t("js_server_answered", { status: r.status }));
      const isEmail = endpoint === "/analyse";
      render(d, isEmail);
      if (isEmail && d.text_agent_used !== false) {
        fetch(API + "/explain", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) })
          .then((x) => (x.ok ? x.json() : Promise.reject(new Error(`HTTP ${x.status}`))))
          .then((x) => renderLime(x.features))
          .catch(() => { const s = $("lime"); if (s) s.textContent = t("js_lime_unavailable"); });
      } else if (isEmail) {
        const s = $("lime"); if (s) s.textContent = t("js_lime_too_little");
      }
    } catch (err) {
      showError(t("js_failed"), err.message || String(err));
    } finally {
      submit.disabled = false;
      submit.textContent = submitLabel;
    }
  });
})();
